INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('A', 'a', 1, '/eɪ/', '/æ/', '/eɪ/', '嘴巴张大，嘴角向两边咧开，舌尖抵住下齿，就像马上要咬一个大苹果！', '斜线下，斜线下，中间画一杠。', '蚂蚁蚂蚁爬手臂，/æ/ /æ/ /æ/!', 'Ants, ants, on my arm, /æ/ /æ/ /æ/!', '[{"word": "apple", "ipa": "/ˈæpəl/", "meaning_cn": "苹果", "emoji": "🍎"}, {"emoji": "🐜", "meaning_cn": "蚂蚁", "ipa": "/ænt/", "word": "ant"}, {"emoji": "🐊", "meaning_cn": "鳄鱼", "ipa": "/ˈælɪɡeɪtər/", "word": "alligator"}, {"meaning_cn": "箭头", "emoji": "➡️", "word": "arrow", "ipa": "/ˈæroʊ/"}]'::jsonb, '你知道吗？''alligator'' 这个词来自西班牙语''el lagarto''，意思就是‘蜥蜴’！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('B', 'b', 2, '/biː/', '/b/', '', '嘴唇闭紧，然后突然张开，把气流送出来，就像在说‘球’(b-b-ball)！', '一根直线，两个半圆。', '把球带来，把棒带来，/b/ /b/ /b/!', 'Bring your bat and bring your ball, /b/ /b/ /b/!', '[{"meaning_cn": "球", "emoji": "⚽", "word": "ball", "ipa": "/bɔːl/"}, {"ipa": "/bɔɪ/", "word": "boy", "emoji": "👦", "meaning_cn": "男孩"}, {"meaning_cn": "床", "emoji": "🛏️", "word": "bed", "ipa": "/bed/"}, {"word": "banana", "ipa": "/bəˈnænə/", "meaning_cn": "香蕉", "emoji": "🍌"}]'::jsonb, '世界上最受欢迎的水果之一就是香蕉(banana)哦！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('C', 'c', 3, '/siː/', '/k/', '', '嘴巴微微张开，舌根抬起抵住软腭，然后快速送气，发出清脆的/k/音，像敲响板的声音。', '画一个大大的半圆。', '我们在敲响板，/k/ /k/ /k/!', 'We are clicking castanets, /k/ /k/ /k/!', '[{"word": "cat", "ipa": "/kæt/", "meaning_cn": "猫", "emoji": "🐱"}, {"emoji": "🚗", "meaning_cn": "汽车", "ipa": "/kɑːr/", "word": "car"}, {"ipa": "/keɪk/", "word": "cake", "emoji": "🎂", "meaning_cn": "蛋糕"}, {"emoji": "☕", "meaning_cn": "杯子", "ipa": "/kʌp/", "word": "cup"}]'::jsonb, '字母C的发音有时是/k/，有时是/s/（比如在''city''里）。是不是很有趣？') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('D', 'd', 4, '/diː/', '/d/', '', '舌尖抵住上牙齿后面，然后用力弹开，声带振动，发出‘嘚嘚嘚’的声音，像在打鼓。', '一根直线，一个大半圆。', '看我打鼓，/d/ /d/ /d/!', 'See me play on my drum, /d/ /d/ /d/!', '[{"emoji": "🐶", "meaning_cn": "狗", "ipa": "/dɒɡ/", "word": "dog"}, {"word": "duck", "ipa": "/dʌk/", "meaning_cn": "鸭子", "emoji": "🦆"}, {"emoji": "🚪", "meaning_cn": "门", "ipa": "/dɔːr/", "word": "door"}, {"word": "dolphin", "ipa": "/ˈdɒlfɪn/", "meaning_cn": "海豚", "emoji": "🐬"}]'::jsonb, '狗狗的鼻子是独一无二的，就像人类的指纹一样！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('E', 'e', 5, '/iː/', '/e/', '/iː/', '嘴巴微微张开，舌尖轻轻抵住下牙，就像要把鸡蛋敲开一样，发出/e/ /e/ /e/的声音。', '一根直线，上面一横，中间一横，下面一横。', '敲开鸡蛋，/e/ /e/ /e/!', 'Eggs in the pan, /e/ /e/ /e/. Crack the egg like this /e/!', '[{"emoji": "🥚", "meaning_cn": "鸡蛋", "ipa": "/eɡ/", "word": "egg"}, {"word": "elephant", "ipa": "/ˈelɪfənt/", "meaning_cn": "大象", "emoji": "🐘"}, {"emoji": "🧝", "meaning_cn": "精灵", "ipa": "/elf/", "word": "elf"}, {"ipa": "/ˈenvələʊp/", "word": "envelope", "emoji": "✉️", "meaning_cn": "信封"}]'::jsonb, '大象(elephant)是陆地上最大的动物，它们的耳朵很大，可以用来散热！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('F', 'f', 6, '/ef/', '/f/', '', '上牙轻轻咬住下嘴唇，然后吹气，就像给充气鱼放气一样。', '一根直线，上面一横，中间一横。', '我的充气鱼漏气了，/f/ /f/ /f/!', 'My friends and I went to the beach with my floating fish. It got a hole, the air came out. /f/ /f/ /f/ /f/ /f/.', '[{"meaning_cn": "鱼", "emoji": "🐟", "word": "fish", "ipa": "/fɪʃ/"}, {"ipa": "/fæn/", "word": "fan", "emoji": "🌬️", "meaning_cn": "风扇"}, {"word": "frog", "ipa": "/frɒɡ/", "meaning_cn": "青蛙", "emoji": "🐸"}, {"ipa": "/faɪv/", "word": "five", "emoji": "5️⃣", "meaning_cn": "五"}]'::jsonb, '你知道吗？数字五(five)的英文单词里也有字母F哦！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('G', 'g', 7, '/dʒiː/', '/ɡ/', '', '舌根抬起，堵住喉咙，然后让气流冲出来，声带振动，就像水被冲下水道的声音。', '先画一个C，然后加一横，再加一竖。', '水在往下流，/g/ /g/ /g/!', 'The water gurgles down the drain, /g/ /g/ /g/!', '[{"ipa": "/ɡɜːrl/", "word": "girl", "emoji": "👧", "meaning_cn": "女孩"}, {"word": "gate", "ipa": "/ɡeɪt/", "meaning_cn": "大门", "emoji": "🚪"}, {"word": "goose", "ipa": "/ɡuːs/", "meaning_cn": "鹅", "emoji": "🦢"}, {"meaning_cn": "礼物", "emoji": "🎁", "word": "gift", "ipa": "/ɡɪft/"}]'::jsonb, '字母G也有两种发音，一种是/g/ (gate)，一种是/dʒ/ (giraffe)！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('H', 'h', 8, '/eɪtʃ/', '/h/', '', '嘴巴张开，向外哈气，就像跑累了在喘气一样。', '一竖一竖，中间一横。', '我喜欢跳房子，/h/ /h/ /h/!', 'I like to hop, hop, hop, all around. I like to hop, hop, hop, up and down.', '[{"word": "hat", "ipa": "/hæt/", "meaning_cn": "帽子", "emoji": "👒"}, {"ipa": "/hænd/", "word": "hand", "emoji": "✋", "meaning_cn": "手"}, {"ipa": "/hɔːrs/", "word": "horse", "emoji": "🐴", "meaning_cn": "马"}, {"word": "house", "ipa": "/haʊs/", "meaning_cn": "房子", "emoji": "🏠"}]'::jsonb, '你的手(hand)上有5个手指，但马(horse)的脚只有一个趾头哦！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('I', 'i', 9, '/aɪ/', '/ɪ/', '/aɪ/', '嘴巴放松，微微张开，舌头向前，发出/ɪ/ /ɪ/ /ɪ/的声音，就像小老鼠在叫。', '一根直线，上面一横，下面一横。', '小老鼠身上有墨水，/ɪ/ /ɪ/ /ɪ/!', 'Inky the mouse is my pet. She spilled the ink and got wet. The ink it spread all over the desk. /ɪ/ /ɪ/ /ɪ/ /ɪ/ - Inky''s wet!', '[{"word": "ink", "ipa": "/ɪŋk/", "meaning_cn": "墨水", "emoji": "✒️"}, {"emoji": "🧊", "meaning_cn": "冰屋", "ipa": "/ˈɪɡluː/", "word": "igloo"}, {"word": "iguana", "ipa": "/ɪˈɡwɑːnə/", "meaning_cn": "鬣蜥", "emoji": "🦎"}, {"emoji": "🐞", "meaning_cn": "昆虫", "ipa": "/ˈɪnsekt/", "word": "insect"}]'::jsonb, '冰屋(igloo)是用雪砖盖的，但是里面却很暖和！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('J', 'j', 10, '/dʒeɪ/', '/dʒ/', '', '舌尖顶住上颚，嘴唇向前突出，然后气流冲出，声带振动，就像果冻在晃动。', '向下的钩子，上面加一横。', '果冻和果酱，/dʒ/ /dʒ/ /dʒ/!', 'Jelly and jam, jiggling on a plate, oh what will I eat with it? /dʒ/ /dʒ/ /dʒ/ /dʒ/ /dʒ/!', '[{"word": "jam", "ipa": "/dʒæm/", "meaning_cn": "果酱", "emoji": "🍓"}, {"emoji": "✈️", "meaning_cn": "喷气式飞机", "ipa": "/dʒet/", "word": "jet"}, {"ipa": "/ˈdʒelifɪʃ/", "word": "jellyfish", "emoji": "🪼", "meaning_cn": "水母"}, {"emoji": "🧃", "meaning_cn": "果汁", "ipa": "/dʒuːs/", "word": "juice"}]'::jsonb, '水母(jellyfish)没有大脑，也没有心脏哦，但它们在地球上已经生活了数亿年！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('K', 'k', 11, '/keɪ/', '/k/', '', '和字母C的发音一样！嘴巴微微张开，舌根抬起，快速送气，发出清脆的/k/音，像放风筝时线被拉紧的声音。', '一根直线，然后一个小于号。', '风筝飞呀飞，/k/ /k/ /k/!', 'Kites are flying in the sky, /k/ /k/ /k/!', '[{"emoji": "🪁", "meaning_cn": "风筝", "ipa": "/kaɪt/", "word": "kite"}, {"meaning_cn": "国王", "emoji": "👑", "word": "king", "ipa": "/kɪŋ/"}, {"ipa": "/kiː/", "word": "key", "emoji": "🔑", "meaning_cn": "钥匙"}, {"ipa": "/ˌkæŋɡəˈruː/", "word": "kangaroo", "emoji": "🦘", "meaning_cn": "袋鼠"}]'::jsonb, '袋鼠(kangaroo)宝宝出生时非常小，只有一颗果冻豆那么大，然后会爬到妈妈的育儿袋里长大。') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('L', 'l', 12, '/el/', '/l/', '', '舌尖顶住上牙齿后面，声带振动，就像在舔一个美味的棒棒糖。', '一竖，一横。', '我们舔着棒棒糖，/l/ /l/ /l/!', 'We lick our lollipops, /l/ /l/ /l/!', '[{"ipa": "/ˈlaɪən/", "word": "lion", "emoji": "🦁", "meaning_cn": "狮子"}, {"ipa": "/leɡ/", "word": "leg", "emoji": "🦵", "meaning_cn": "腿"}, {"meaning_cn": "叶子", "emoji": "🍁", "word": "leaf", "ipa": "/liːf/"}, {"ipa": "/ˈlemən/", "word": "lemon", "emoji": "🍋", "meaning_cn": "柠檬"}]'::jsonb, '狮子(lion)的吼声非常响亮，在8公里外都能听到！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('M', 'm', 13, '/em/', '/m/', '', '嘴唇闭紧，气流从鼻子里出来，发出‘嗯’的声音，就像看到美味的食物时一样。', '一竖，斜线，斜线，再一竖。', '妈妈做了美味大餐，/m/ /m/ /m/!', 'The mum and the dad make many meals for their hungry children. /m/ /m/ /m/ /m/ /m/.', '[{"emoji": "🐒", "meaning_cn": "猴子", "ipa": "/ˈmʌŋki/", "word": "monkey"}, {"meaning_cn": "牛奶", "emoji": "🥛", "word": "milk", "ipa": "/mɪlk/"}, {"word": "moon", "ipa": "/muːn/", "meaning_cn": "月亮", "emoji": "🌙"}, {"meaning_cn": "老鼠", "emoji": "🐭", "word": "mouse", "ipa": "/maʊs/"}]'::jsonb, '月亮(moon)上没有风，所以宇航员在上面留下的脚印会一直都在！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('N', 'n', 14, '/en/', '/n/', '', '舌尖顶住上颚，鼻子出气，发出嗯嗯嗯的声音，感觉鼻子在振动。', '大写N，一笔写下，二笔斜下，三笔再写下。小写n，一笔写下，然后向上弯曲成拱形。', '飞机噪音嗯嗯嗯, n, n, n。', 'Hear the aeroplane, n-n-n! Hear the aeroplane, n-n-n! ...making lots of noise!', '[{"meaning_cn": "鼻子", "ipa": "/nəʊz/", "emoji": "👃", "word": "nose"}, {"meaning_cn": "九", "ipa": "/naɪn/", "emoji": "9️⃣", "word": "nine"}, {"ipa": "/net/", "word": "net", "emoji": "🥅", "meaning_cn": "网"}, {"word": "noodle", "emoji": "🍜", "ipa": "/ˈnuːdl/", "meaning_cn": "面条"}]'::jsonb, '字母''N''在英语单词中出现的频率很高，很多常见的词都有它！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('O', 'o', 15, '/əʊ/', '/ɒ/', '/əʊ/', '短音/ɒ/：嘴巴张成圆形，舌头放低，快速发音“哦”。长音/əʊ/：嘴巴从圆形慢慢合拢，听起来像字母O的名字。', '大写O和小写o都是一个圈圈，一笔完成！', '电灯开关哦哦哦, o, o, o。', 'Now it’s dark, o-o-o, the lights go on! Time for bed, o-o-o, the lights go off!', '[{"meaning_cn": "橙子", "ipa": "/ˈɒrɪndʒ/", "word": "orange", "emoji": "🍊"}, {"meaning_cn": "章鱼", "ipa": "/ˈɒktəpəs/", "emoji": "🐙", "word": "octopus"}, {"ipa": "/ɒn/", "word": "on", "emoji": "🔛", "meaning_cn": "在...上面"}, {"emoji": "👐", "word": "open", "ipa": "/ˈəʊpən/", "meaning_cn": "打开"}]'::jsonb, '字母''O''是第三个最常见的元音字母哦！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('P', 'p', 16, '/piː/', '/p/', '', '双唇紧闭，然后突然张开，把气流喷出去，发出“噗”的声音，非常短促。', '大写P，先写一竖，再在上面画个半圆。小写p，先写一竖，位置低一点，再在上面画个半圆。', '吹灭蜡烛ppp, p, p, p。', 'Puff out the candles on the pink pig cake. p-p-p! p-p-p!', '[{"meaning_cn": "猪", "ipa": "/pɪɡ/", "emoji": "🐷", "word": "pig"}, {"emoji": "🖊️", "word": "pen", "ipa": "/pen/", "meaning_cn": "钢笔"}, {"ipa": "/ˈpændə/", "emoji": "🐼", "word": "panda", "meaning_cn": "熊猫"}, {"meaning_cn": "公园", "word": "park", "emoji": "🏞️", "ipa": "/pɑːk/"}]'::jsonb, '字母''P''和''B''发音很像，但是发''P''的时候，声带不振动，你可以把手放在喉咙上感觉一下！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('Q', 'q', 17, '/kjuː/', '/kw/', '', '嘴巴先做发/k/的准备，然后快速滑向/w/的音，听起来像“夸”。', '大写Q，先画一个大圈圈，再在右下角画一小撇。小写q，先画一个半圆，再写一竖，最后带个小钩。', '鸭子嘎嘎kw kw kw, q, q, q。', 'The duck in the pond says quack, quack, quack! qu-qu-qu!', '[{"word": "queen", "emoji": "👑", "ipa": "/kwiːn/", "meaning_cn": "女王"}, {"ipa": "/kwɪlt/", "word": "quilt", "emoji": "🛌", "meaning_cn": "被子"}, {"ipa": "/ˈkwaɪət/", "emoji": "🤫", "word": "quiet", "meaning_cn": "安静的"}, {"word": "quick", "emoji": "⚡", "ipa": "/kwɪk/", "meaning_cn": "快速的"}]'::jsonb, '在英语中，字母''Q''后面几乎总是跟着字母''U''，它们是形影不离的好朋友！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('R', 'r', 18, '/ɑː/', '/r/', '', '嘴唇微微撅起，舌尖向后卷，但不要碰到任何地方，发出“rrrrr”的声音，像小狗在咆哮。', '大写R，先写一竖，再画个半圆，最后画一撇。小写r，先写一竖，再向上弯曲一点点。', '小狗咆哮rrr, r, r, r。', 'See my puppy rip the rag. r-r-r! r-r-r! When he pulls so hard.', '[{"ipa": "/ˈræbɪt/", "emoji": "🐰", "word": "rabbit", "meaning_cn": "兔子"}, {"ipa": "/red/", "word": "red", "emoji": "🔴", "meaning_cn": "红色的"}, {"meaning_cn": "跑", "ipa": "/rʌn/", "emoji": "🏃", "word": "run"}, {"ipa": "/ˈrəʊbɒt/", "word": "robot", "emoji": "🤖", "meaning_cn": "机器人"}]'::jsonb, '你知道吗？在某些英语口音里，单词末尾的''r''是不发音的！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('S', 's', 19, '/es/', '/s/', '', '牙齿微微合拢，舌尖靠近上牙龈，气流从牙缝中挤出，发出“嘶嘶”的声音，像小蛇一样。', '大写S和小写s都像一条弯弯曲曲的小蛇，一笔画成！', '小蛇嘶嘶sss, s, s, s。', 'The snake is in the grass. s-s-s! s-s-s! The snake is in the grass.', '[{"emoji": "☀️", "word": "sun", "ipa": "/sʌn/", "meaning_cn": "太阳"}, {"meaning_cn": "六", "emoji": "6️⃣", "word": "six", "ipa": "/sɪks/"}, {"meaning_cn": "看见", "emoji": "👀", "word": "see", "ipa": "/siː/"}, {"word": "snake", "emoji": "🐍", "ipa": "/sneɪk/", "meaning_cn": "蛇"}]'::jsonb, '字母''S''可以发出/s/的音，也可以发出/z/的音，比如在单词''is''里面！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('T', 't', 20, '/tiː/', '/t/', '', '舌尖顶住上牙龈，然后突然放开，气流冲出，发出短促的“特”的声音。', '大写T，先写一横，再在中间写一竖。小写t，先写一竖，再在中间画一小横。', '观看网球t t t, t, t, t。', 'When I watch the tennis game, t-t-t, t-t-t, ...my head goes back and forth.', '[{"meaning_cn": "老虎", "word": "tiger", "emoji": "🐯", "ipa": "/ˈtaɪɡə(r)/"}, {"ipa": "/ten/", "emoji": "🔟", "word": "ten", "meaning_cn": "十"}, {"ipa": "/ˈtiːtʃə(r)/", "word": "teacher", "emoji": "👩‍🏫", "meaning_cn": "老师"}, {"emoji": "🧸", "word": "toy", "ipa": "/tɔɪ/", "meaning_cn": "玩具"}]'::jsonb, '字母''T''发音时，如果把手放在嘴前，能感觉到很强的气流！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('U', 'u', 21, '/juː/', '/ʌ/', '/juː/', '短音/ʌ/：嘴巴微微张开，舌头放松，发出短促的“啊”音，像肚子被轻轻打了一下。长音/juː/：听起来像字母U的名字 ''you''。', '大写U，从上往下画一个弧线再上来。小写u，先画一个向下的弧线，再加一小竖。', '撑开雨伞a a a, u, u, u。', 'Up go umbrellas, u-u-u! Up go umbrellas, u-u-u! ...when it starts to rain.', '[{"meaning_cn": "雨伞", "word": "umbrella", "emoji": "☂️", "ipa": "/ʌmˈbrelə/"}, {"meaning_cn": "向上", "ipa": "/ʌp/", "word": "up", "emoji": "⬆️"}, {"meaning_cn": "在...下面", "ipa": "/ˈʌndə(r)/", "emoji": "👇", "word": "under"}, {"meaning_cn": "叔叔；舅舅", "emoji": "👨", "word": "uncle", "ipa": "/ˈʌŋkl/"}]'::jsonb, '字母''U''和''V''在古代拉丁语里是同一个字母，后来才慢慢分开的！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('V', 'v', 22, '/viː/', '/v/', '', '上牙齿轻轻咬住下嘴唇，然后发出声音，感觉嘴唇在振动，像开着小汽车“呜呜呜”。', '大写V和小写v都像一个胜利的手势，从上往下写一个斜线，再往上写一个斜线。', '开着货车vvv, v, v, v。', 'Drive the van around the village. v-v-v! v-v-v! Drive the van around the village.', '[{"meaning_cn": "货车", "ipa": "/væn/", "word": "van", "emoji": "🚐"}, {"meaning_cn": "背心", "ipa": "/vest/", "word": "vest", "emoji": "🎽"}, {"meaning_cn": "小提琴", "ipa": "/ˌvaɪəˈlɪn/", "emoji": "🎻", "word": "violin"}, {"meaning_cn": "兽医", "word": "vet", "emoji": "👨‍⚕️", "ipa": "/vet/"}]'::jsonb, '''V''是字母表里唯一一个发音时需要牙齿和嘴唇配合的辅音哦！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('W', 'w', 23, '/ˈdʌbljuː/', '/w/', '', '嘴巴撅成圆形，然后快速滑向后面的元音，发出“我”的声音。', '大写W，写两个V连在一起。小写w，也是写两个u或v连在一起，但是小一点。', '风儿呼呼www, w, w, w。', 'I see the wind, w-w-w, blowing the leaves around.', '[{"meaning_cn": "风", "ipa": "/wɪnd/", "emoji": "💨", "word": "wind"}, {"emoji": "💧", "word": "water", "ipa": "/ˈwɔːtə(r)/", "meaning_cn": "水"}, {"meaning_cn": "窗户", "ipa": "/ˈwɪndəʊ/", "word": "window", "emoji": "🖼️"}, {"ipa": "/wɒtʃ/", "emoji": "⌚", "word": "watch", "meaning_cn": "手表"}]'::jsonb, '字母''W''的名字是''double-u''（双U），因为它看起来就像两个U连在一起！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('X', 'x', 24, '/eks/', '/ks/', '', '这个音由/k/和/s/两个音组成，发音时要快，听起来像“科斯”。', '大写X和小写x都像一个叉叉，先写一撇，再写一捺。', 'X光照片ks ks ks, x, x, x。', 'Take an X-ray, ks-ks-ks. Take an X-ray, ks-ks-ks. ... of my hand.', '[{"word": "box", "emoji": "📦", "ipa": "/bɒks/", "meaning_cn": "盒子"}, {"meaning_cn": "狐狸", "ipa": "/fɒks/", "word": "fox", "emoji": "🦊"}, {"ipa": "/sɪks/", "emoji": "6️⃣", "word": "six", "meaning_cn": "六"}, {"meaning_cn": "修理", "emoji": "🔧", "word": "fix", "ipa": "/fɪks/"}]'::jsonb, '以''X''开头的单词非常少，所以我们通常用包含''x''的单词来学习它的发音，比如 box 和 fox！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('Y', 'y', 25, '/waɪ/', '/j/', '', '嘴巴做发“一”的口型，舌头抬高，然后快速滑向后面的元音，声音很短，像‘呀’。', '大写Y，先写一个小v，再在下面加一竖。小写y，像一个带尾巴的u。', '吃着酸奶y y y, y, y, y。', 'I like to eat, eat, eat, yogurt and bananas. y-y-y!', '[{"meaning_cn": "悠悠球", "emoji": "🪀", "word": "yo-yo", "ipa": "/ˈjəʊ jəʊ/"}, {"ipa": "/ˈjeləʊ/", "word": "yellow", "emoji": "🟡", "meaning_cn": "黄色的"}, {"meaning_cn": "是的", "word": "yes", "emoji": "👍", "ipa": "/jes/"}, {"meaning_cn": "酸奶", "word": "yogurt", "emoji": "🍦", "ipa": "/ˈjɒɡət/"}]'::jsonb, '字母''Y''很特别，有时它当辅音（比如在''yes''里），有时它又当元音（比如在''fly''里）！') ON CONFLICT (letter_upper) DO NOTHING;
INSERT INTO public.primary_letters (letter_upper, letter_lower, sort_order, letter_name_ipa, phonics_short_ipa, phonics_long_ipa, mouth_tip_cn, stroke_order_cn, chant_cn, chant_en, example_words, fun_fact_cn) VALUES ('Z', 'z', 26, '/zed/', '/z/', '', '和发/s/音的口型一样，但是要发出声音，感觉声带在振动，像小蜜蜂“嗡嗡嗡”。', '大写Z和小写z都是一笔写成，先写一横，再写一斜，最后再写一横。', '蜜蜂嗡嗡zzz, z, z, z。', 'Did you ever hear a bee buzz, a bee buzz, a bee buzz? Did you ever hear a bee buzz, z-z-z, like this?', '[{"meaning_cn": "动物园", "ipa": "/zuː/", "emoji": "🦁", "word": "zoo"}, {"word": "zebra", "emoji": "🦓", "ipa": "/ˈzebrə/", "meaning_cn": "斑马"}, {"meaning_cn": "零", "emoji": "0️⃣", "word": "zero", "ipa": "/ˈzɪərəʊ/"}, {"meaning_cn": "拉链", "ipa": "/zɪp/", "emoji": "🤐", "word": "zip"}]'::jsonb, '字母''Z''是英语字母表里的最后一个字母，它在单词里出现得最少哦！') ON CONFLICT (letter_upper) DO NOTHING;
