INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('hello', '/həˈləʊ/', 'int.', '你好', 'A word to greet someone', 'Hello, I am Lily.', '你好，我是莉莉。', 5, 1, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('hi', '/haɪ/', 'int.', '嗨', 'A friendly way to say hello', 'Hi, what is your name?', '嗨，你叫什么名字？', 5, 2, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('name', '/neɪm/', 'n.', '名字', 'What someone is called', 'My name is Tom.', '我的名字是汤姆。', 5, 3, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('I', '/aɪ/', 'pron.', '我', 'The person who is speaking', 'I am a boy.', '我是一个男孩。', 5, 4, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('goodbye', '/ˌɡʊdˈbaɪ/', 'int.', '再见', 'What you say when you leave', 'Goodbye, see you tomorrow.', '再见，明天见。', 5, 5, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('bye', '/baɪ/', 'int.', '再见', 'A short way to say goodbye', 'Bye, Mom!', '再见，妈妈！', 5, 6, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('am', '/æm/', 'v.', '是', 'Used with ''I'' to say who you are', 'I am seven years old.', '我七岁了。', 5, 7, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('is', '/ɪz/', 'v.', '是', 'Used to say who someone is', 'Her name is Amy.', '她的名字是艾米。', 5, 8, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('you', '/juː/', 'pron.', '你；你们', 'The person you are talking to', 'How are you?', '你好吗？', 5, 9, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('what', '/wɒt/', 'pron.', '什么', 'Used to ask for information', 'What is your name?', '你叫什么名字？', 5, 10, 'primary_greetings', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('family', '/ˈfæməli/', 'n.', '家庭', 'A group with parents and children.', 'This is my happy family.', '这是我快乐的家庭。', 5, 1, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('father', '/ˈfɑːðər/', 'n.', '爸爸', 'A male parent.', 'My father is a doctor.', '我的爸爸是一名医生。', 5, 2, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('mother', '/ˈmʌðər/', 'n.', '妈妈', 'A female parent.', 'Her mother is a teacher.', '她的妈妈是一位老师。', 5, 3, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('brother', '/ˈbrʌðər/', 'n.', '兄弟', 'A boy with the same parents.', 'He is my little brother.', '他是我的弟弟。', 5, 4, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('sister', '/ˈsɪstər/', 'n.', '姐妹', 'A girl with the same parents.', 'I have a big sister.', '我有一个姐姐。', 5, 5, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('home', '/hoʊm/', 'n.', '家', 'The place where you live.', 'Let''s go home after school.', '我们放学后回家吧。', 5, 6, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('friend', '/frɛnd/', 'n.', '朋友', 'Someone you like and play with.', 'You are my best friend.', '你是我最好的朋友。', 5, 7, 'primary_family', 'primary', 1, 'BOTH');
INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('grandfather', '/ˈgrænˌfɑːðər/', 'n.', '(外)祖父', 'The father of your parent.', 'My grandfather is very kind.', '我的爷爷非常和蔼。', 5, 8, 'primary_family', 'primary', 1, 'BOTH');
