INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('sun', '/sʌn/', 'n.', '太阳', 'the star that shines during the day', 'The sun is big and yellow.', '太阳又大又黄。', 5, 1, 'primary_nature', 'primary', 1, 'BOTH');
