INSERT INTO public.gaokao_vocab (word, phonetic, pos, meaning_cn, meaning_en, example_en, example_cn, star_level, freq_rank, theme, stage, frequency_band, accent) VALUES ('surprised', '/sərˈpraɪzd/', 'adj.', '惊讶的', 'feeling shocked by something new', 'She was very surprised.', '她非常惊讶。', 3, 9, 'primary_feelings', 'primary', 1, 'BOTH');
